mapper.select:
SELECT
    COUNT(DISTINCT rd.id) as totalDispatches,
    SUM(rd.quantity) as totalResources
FROM resource_dispatch rd
LEFT JOIN emergency_response r ON rd.response_id = r.id
LEFT JOIN emergency_event e ON r.event_id = e.id
WHERE rd.deleted = false

      AND e.is_drill = FALSE


      AND rd.create_time >= #{reqVO.startTime}


      AND rd.create_time <= #{reqVO.endTime}


      AND rd.resource_type = #{reqVO.resourceType}


      AND r.response_level = #{reqVO.responseLevel}

SELECT rd.resource_type as resourceType, rd.resource_type as typeName, COUNT(DISTINCT rd.id) as dispatchCount, SUM(rd.quantity) as totalResources, ROUND(AVG(rd.quantity), 2) as avgResourcesPerDispatch FROM resource_dispatch rd LEFT JOIN emergency_response r ON rd.response_id = r.id LEFT JOIN emergency_event e ON r.event_id = e.id WHERE rd.deleted = false
AND e.is_drill = FALSE
AND rd.create_time >= #{reqVO.startTime}
AND rd.create_time <= #{reqVO.endTime}
AND r.response_level = #{reqVO.responseLevel}
GROUP BY rd.resource_type ORDER BY dispatchCount DESC

SELECT r.response_level as responseLevel, COUNT(DISTINCT rd.id) as dispatchCount, ROUND(AVG(rd.quantity), 2) as avgResources, ROUND(COUNT(DISTINCT rd.id) * 100.0 / SUM(COUNT(DISTINCT rd.id)) OVER (), 2) as utilizationRate FROM resource_dispatch rd LEFT JOIN emergency_response r ON rd.response_id = r.id LEFT JOIN emergency_event e ON r.event_id = e.id WHERE rd.deleted = false
AND e.is_drill = FALSE
AND rd.create_time >= #{reqVO.startTime}
AND rd.create_time <= #{reqVO.endTime}
AND rd.resource_type = #{reqVO.resourceType}
GROUP BY r.response_level ORDER BY responseLevel

SELECT rd.resource_id as resourceId, rd.resource_name as resourceName, rd.resource_type as resourceType, COUNT(*) as usageCount, SUM(EXTRACT(EPOCH FROM (COALESCE(rd.recovered_time, CURRENT_TIMESTAMP) - rd.dispatch_time))/60) as totalUsageTime FROM resource_dispatch rd LEFT JOIN emergency_response r ON rd.response_id = r.id LEFT JOIN emergency_event e ON r.event_id = e.id WHERE rd.deleted = false AND rd.status IN ('dispatched', 'recovered')
AND e.is_drill = FALSE
AND rd.create_time >= #{reqVO.startTime}
AND rd.create_time <= #{reqVO.endTime}
AND rd.resource_type = #{reqVO.resourceType}
AND r.response_level = #{reqVO.responseLevel}
GROUP BY rd.resource_id, rd.resource_name, rd.resource_type ORDER BY usageCount DESC LIMIT 10

SELECT rp.type as resourceType, rp.type as typeName, COUNT(DISTINCT rp.id) as totalResources, COUNT(DISTINCT CASE WHEN rp.status = 'in_use' THEN rp.id END) as inUseResources, ROUND(COUNT(DISTINCT CASE WHEN rp.status = 'in_use' THEN rp.id END) * 100.0 / COUNT(DISTINCT rp.id), 2) as utilizationRate FROM resource_pool rp WHERE rp.deleted = false
AND rp.type = #{reqVO.resourceType}
GROUP BY rp.type ORDER BY utilizationRate DESC
